def transform(grid):
    H = len(grid); W = len(grid[0])
    import numpy as np
    g = np.array(grid)
    # find rectangles
    colors = [c for c in set(g.flatten()) if c != 0]
    rects = {}
    for c in colors:
        ys, xs = np.where(g == c)
        rects[c] = (ys.min(), ys.max(), xs.min(), xs.max())
    out = np.zeros((H, W), dtype=int)
    def put(r0, c0, h, w, col, ring=True):
        if ring:
            for y in range(r0 - 1, r0 + h + 1):
                for x in range(c0 - 1, c0 + w + 1):
                    if 0 <= y < H and 0 <= x < W:
                        out[y, x] = 4
    def rect(r0, c0, h, w, col):
        for y in range(r0, r0 + h):
            for x in range(c0, c0 + w):
                if 0 <= y < H and 0 <= x < W:
                    edge = y in (r0, r0 + h - 1) or x in (c0, c0 + w - 1)
                    out[y, x] = col if edge else 0
    info = []
    for c, (a, b, l, r) in rects.items():
        info.append((b - a + 1, r - l + 1, c))
    info.sort(key=lambda t: -(t[0] * t[1]))
    hub = info[0]
    others = sorted(info[1:], key=lambda t: t[0] * t[1])
    # others: smaller area first (3x3-like), then 3x4-like
